#!/usr/bin/env python3
from pathlib import Path
import datetime,hashlib,json,subprocess,sys,time
OUT=Path(__file__).resolve().parent
PRE=OUT.parent
ROOT=PRE.parents[1]
CANDIDATE=ROOT/'verification/swift-initial-profile-construction-implementation'
def sha(b):return hashlib.sha256(b).hexdigest()
def write(n,d):(OUT/n).write_text(json.dumps(d,indent=2,sort_keys=True)+'\n')
def verify(base,name,digest):
 b=(base/name).read_bytes();assert sha(b)==digest;d=json.loads(b)
 for m in d['members']:
  b=(base/m['path']).read_bytes();assert len(b)==m['bytes'] and sha(b)==m['sha256'],m['path']
 return {'seal_sha256':digest,'members':d['member_count'],'bytes':d['total_bytes']}
def main():
 assert not (OUT/'seal.json').exists()
 pre=verify(PRE,'preaccess-seal.json','b9048e6edd9941ca3293badd322d89fbfb16a25c1cb02502896d38c589b4295a')
 old=json.loads((PRE/'preaccess-seal.json').read_text());oldpaths={m['path'] for m in old['members']}|{'preaccess-seal.json','preaccess-seal.sha256'}
 actualpaths={str(p.relative_to(PRE)) for p in PRE.rglob('*') if p.is_file() and 'actual-review' not in p.relative_to(PRE).parts};assert oldpaths==actualpaths
 candidate=verify(CANDIDATE,'seal.json','50d1c32174ee4cbcade6095039261ea0ff8eed05680322bfb59b5de0dd4cd8b1')
 for folder,digest in [('foundation-findings','9d1927862f202d409336c66b2c30e9800522bda1f70e2a5c8ed3c039e91c4627'),('source-action-findings','61d0f1e72be8c2c631b3e6cc45272f3a737b15ac0b852843fa1d401e6a8b4e4f')]:verify(OUT/folder,'seal.json',digest)
 start=time.monotonic();argv=[sys.executable,str(OUT/'audit_actual.py')];r=subprocess.run(argv,cwd=ROOT,capture_output=True,timeout=30)
 (OUT/'final-audit.stdout').write_bytes(r.stdout);(OUT/'final-audit.stderr').write_bytes(r.stderr)
 write('final-audit-receipt.json',{'schema':1,'argv':argv,'cwd':str(ROOT),'exit_code':r.returncode,'elapsed_seconds':time.monotonic()-start,'timeout_seconds':30,'checker_sha256':sha((OUT/'audit_actual.py').read_bytes()),'python':sys.version,'python_executable_sha256':sha(Path(sys.executable).read_bytes()),'stdout_sha256':sha(r.stdout),'stderr_sha256':sha(r.stderr),'no_native_capture_or_process_inventory':True})
 assert r.returncode==0
 matrix=json.loads((OUT/'review-matrix.json').read_text());assert len(matrix['controls'])==29 and not any('PENDING' in m['candidate_status'] for m in matrix['controls'])
 abstract=json.loads((OUT/'abstract-action-reconciliation.json').read_text());assert abstract['same_unit_reconciled'] and not abstract['all_actual_authored_source_evaluations_bound_qualified']
 revision=subprocess.run(['git','rev-parse','HEAD'],cwd=ROOT,capture_output=True,timeout=10);assert revision.returncode==0
 (OUT/'source-revision-context.stdout').write_bytes(revision.stdout);(OUT/'source-revision-context.stderr').write_bytes(revision.stderr)
 corrections=[]
 for p in sorted((OUT/'root-corrections').iterdir()):corrections.append({'path':str(p.relative_to(OUT)),'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())})
 write('decision.json',{'schema':1,'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'decision':'Independent scoped actual-source construction/header/rows/accounting review accepted under exact root foundation and abstract-action scope corrections; root acceptance remains separate','accountable_reviewer':'independent actual-source lane with254-member frozen preaccess controls','candidate_seal_sha256':candidate['seal_sha256'],'candidate_source_tree_sha256':'71a00fde8a43aef5a7e6104932d3f0ca10a5989fb686c99828937b05aa363c7c','preaccess_seal_sha256':pre['seal_sha256'],'final_custody_reverified':{'preaccess':pre,'candidate':candidate,'preaccess_pathset_restored_and_exact':True},'source_revision_context':revision.stdout.decode().strip(),'source_revision_context_is_not_distribution_identity':True,'distribution_paths':140,'declared_host_support_paths':11,'independent_review_accepted':True,'independent_source_object_lifetime_heap_cleanup_accepted':True,'root_accepted':False,'canonical_integrated':False,'new_product_dependency_cap_deadline_or_ledger_change':False,'all29_preaccess_controls_dispositioned':True,'actual_layouts':{'selected_complete_types':165,'additional_complete_helper_types':24,'configurations':['production-host','unit'],'modes':['Debug','optimized'],'only_root_selected_unit_layout_deltas':[122,146,160],'ordinary_dispatcher_absence_both_modes':True},'fresh_final_commands':{'selected_behavior':96,'selected_compiler':25,'independent':28,'total':149,'selected_compiler_observations':22,'independent_compiler_observations':22},'source_place_join':{'production':{'union_bytes':197880,'unchanged_floor_bytes':269080,'headroom_bytes':71200,'prepared_bound_source_derived':330960},'unit':{'union_bytes':197928,'unchanged_floor_bytes':269616,'headroom_bytes':71688,'prepared_bound_source_derived':331496},'original_disjoint_constructor':61880,'original_disjoint_cleanup':62888,'accepted_disjoint_row_union':11912,'no_execution_bootstrap_path_concurrently_live':True,'source_places_are_not_stack_RSS_or_whole_process_memory':True},'source_action_scope':{'abstract_primitive_callsite_plus_requested_IO_ceiling':451173376,'row_same_unit':450652288,'added_same_unit':521088,'same_unit_reconciled':True,'selected_std_primitive_and_closed_pure_callback_counted_once':True,'implementation_retries_and_callback_reevaluations_excluded':True,'actual_all_source_callback_CPU_retry_time_VM_bound_qualified':False,'not_a_capacity_reservation_or_release_gate':True},'cleanup':{'healthy_actual_owned_combined_and_tickets_zero':True,'separate_unit_fault_quarantine_bytes':331496,'separate_unit_fault_quarantine_tickets':1,'unit_fault_actual_displaced_authority_restored':True,'unit_fault_original_first_failure_and_after_cleanup_None_retained':True,'quarantine_is_not_successful_cleanup_or_production_fault_evidence':True,'all_owned_children_reaped_and_compiler_TMP_scratch_removed':True,'single_incidental_unsealed_bytecode_removed_with_hash_receipt':True,'no_native_UI_capture_or_process_inventory':True},'root_corrections':corrections,'limitations':['Strong actual callback/CPU/retry/time/VM execution bound remains unqualified; only selected abstract scalar accepted','Source object/action scopes exclude library/kernel/allocator/scheduler internals, code/static image, arbitrary callers and global process memory','Defensive sealed-owner policy/arithmetic faults unreachable on selected safe target remain source-reviewed rather than executed','Metadata/position syscall faults source-only where safely unobtainable; writer schedules not all kernel-origin','File bytes/offset/acknowledged progress imply no rollback/fsync/durability/digest/immutable custody','Safe synthetic29/67/64 and79966 tiny bodies/static79967 refusal are not historical Swift80k replay','External source/compiler/artifact receipts do not make opaque encoded claims verified','No real retained-descriptor composition/context/final typed result or15-word ledger binding/canonical integration/published package qualification','No new compiler/OS/CI, native/mobile/UI/device/FieldLog/store/operational/GA acceptance'],'all_raw_prior_failures_preserved':True,'source_scope_and_findings':['source-review.md','audit-result.json','review-matrix.json','foundation-findings/seal.json','source-action-findings/seal.json','abstract-action-reconciliation.json'],'runtime_real_binding_FieldLog_GA_accepted':False})
 members=[]
 for p in sorted(OUT.rglob('*')):
  if p.is_file() and str(p.relative_to(OUT)) not in ['seal.json','seal.sha256']:
   b=p.read_bytes();members.append({'path':str(p.relative_to(OUT)),'bytes':len(b),'sha256':sha(b)})
 write('seal.json',{'schema':1,'scope':'Exact independent actual-source review with preserved preaccess and both root-selected corrections; no root/runtime/GA acceptance','member_count':len(members),'total_bytes':sum(m['bytes'] for m in members),'members':members,'excluded':['seal.json','seal.sha256']})
 digest=sha((OUT/'seal.json').read_bytes());(OUT/'seal.sha256').write_text(digest+'  seal.json\n');print(f'INDEPENDENT ACTUAL REVIEW frozen {len(members)} members {sum(m["bytes"] for m in members)} bytes seal SHA256 {digest}')
if __name__=='__main__':main()
